    name = models.CharField(max_length=100)

    class Meta:
        app_label = 'test'

class ChildModel(models.Model):
    name = models.CharField(max_length=100)
    parent = models.ForeignKey(ParentModel, on_delete=models.CASCADE)

    class Meta:
        app_label = 'test'

# Define a serializer that inherits from NestedHyperlinkedModelSerializer
class ChildSerializer(NestedHyperlinkedModelSerializer):
    parent_lookup_kwargs = {'parent_pk': 'parent__pk'}

    class Meta:
        model = ChildModel
        fields = ['url', 'name']

# Create an instance of the serializer
serializer = ChildSerializer()

# Check if parent_lookup_kwargs is correctly set
print("Class-defined parent_lookup_kwargs:", getattr(ChildSerializer, 'parent_lookup_kwargs', None))
