if hasattr(serializer, 'fields') and 'url' in serializer.fields:
    url_field = serializer.fields['url']
    print("URL field parent_lookup_kwargs:", getattr(url_field, 'parent_lookup_kwargs', None))
else:
    print("URL field not yet initialized")
